import model
from model import _energy_for_action,_separatrix_data,_connected_energy,phase_volume
import numpy as np
for d in [.15,.2,.25]:
 print('d',d,'sep',_separatrix_data(d))
 for s in [.1,.15,.5,1,2.2]:
  try: print(s,model.mean_energy(.1438111640371333,d,s))
  except Exception as e:
   print('FAIL',s,e)
   sep=sum(_separatrix_data(d)[1]); print('sepaction',s**1.5*sep)
   z,w=model.quadrature(48); lo=.143811164;hi=1.2*lo
   for x in (lo+hi)/2+(hi-lo)*z/2:
    if x/s**1.5>=sep:
     a=x/s**1.5; tar=2*np.pi*a
     print('x',x,'a',a,'diff',a-sep,'fsep',phase_volume(_separatrix_data(d)[0],d)-tar)
     break
PY"

